const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},put=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let meds=get('prognos-meds',[]),saved=get('prognos-saved',[]),selectedDate=new Date().toLocaleDateString('en-CA'),chat=[],simple=false;
const navs=[['home','⌂','Overview'],['library','▤','Condition library'],['body','♧','Symptom explorer'],['consultant','✧','AI consultant'],['medicines','⊞','Medicine matrix'],['calendar','▦','My care calendar'],['care','♧','Find specialist care'],['mission','◴','Our mission & impact']];
function source(c){return `<div class="source"><a href="${c.source.url}" target="_blank" rel="noopener">${esc(c.source.name)} ↗</a><br>${esc(c.source.credentials)}<br><span class="muted">Source checked ${DATA.checked} · Summary has not been independently clinically reviewed.</span></div>`}
function title(k,t,d){return `<div class="page-top"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div><span class="badge">♧ &nbsp; Evidence before answers</span></div>`}
const names={pots:'POTS',migraine:'Migraine',ibs:'Irritable bowel syndrome',endometriosis:'Endometriosis',hypothyroidism:'Hypothyroidism',anemia:'Iron-deficiency anemia'},icons={pots:'♡',migraine:'◎',ibs:'⌁',endometriosis:'❀',hypothyroidism:'⋈',anemia:'♧'};
function conditionCards(cs){return `<div class="condition-grid">${cs.map(c=>`<button class="condition" onclick="location.hash='condition/${c.id}'"><span class="icon">${icons[c.id]}</span><h3>${names[c.id]} <span style="float:right">↗</span></h3><p>${c.symptoms.slice(0,3).join(' · ')}</p><small>↗ ${esc(c.source.name)}</small></button>`).join('')}</div>`}
function bodyMap(){const full=location.hash.startsWith('#body');return `<iframe class="anatomy-frame ${full?'full':'mini'}" src="anatomy.html${full?'':'?compact=1'}" title="Interactive 3D anatomy explorer" loading="lazy"></iframe>`}

function home(){return `${title('A LITTLE CLARITY, ONE STEP AT A TIME','Your symptoms deserve to be understood.','Explore trusted information. Ask better questions. Find your next step.')}<section class="hero"><svg class="hero-art" viewBox="0 0 160 130"><circle cx="80" cy="65" r="59" fill="none" stroke="#99b27b"/><circle cx="80" cy="65" r="43" fill="none" stroke="#99b27b"/><path d="M60 64h40M80 44v40" stroke="#8ea96b" stroke-width="16" stroke-linecap="round"/></svg><div class="eyebrow">LET’S START WITH HOW YOU FEEL</div><h2>You don’t need the right words.</h2><p>A symptom, a condition, or “I feel dizzy when I stand up.” Start anywhere.</p><form class="searchbox" onsubmit="event.preventDefault();searchGo(this.q.value)"><span>⌕</span><input name="q" aria-label="Search symptoms or conditions" placeholder="Describe a symptom or search a condition…" required><button class="primary">Explore →</button></form><div class="chips">Often explored: ${['Fatigue','Dizziness','Headache','Abdominal pain'].map(x=>`<button class="chip" onclick="searchGo('${x}')">${x}</button>`).join('')}</div></section><div class="grid"><section class="card"><div class="sectionhead"><h2>Where does it hurt?</h2><a href="#body">Explore body map ↗</a></div><p class="sub">Select an area to explore symptoms and possible causes.</p>${bodyMap()}<p class="bodyhint">A starting point for understanding, not a diagnosis.</p></section><section class="card assistant-card"><div class="spark">✧</div><div class="eyebrow">A LITTLE HELP CONNECTING THE DOTS</div><h2>Questions are a good<br>place to start.</h2><p class="sub">Explore source-linked answers and prepare for a more informed conversation with your doctor.</p><button class="question" onclick="askPreset('What can cause dizziness when standing?')">“Why do I feel dizzy when I stand up?” ↗</button><button class="question" onclick="askPreset('How do I prepare for a doctor visit?')">“How do I prepare for my next appointment?” ↗</button><button class="primary" onclick="location.hash='consultant'">Open consultant &nbsp; ✧</button><p class="fine">Source-guided preview · Live AI is not connected</p></section></div><section class="explore"><div class="sectionhead"><h2>A starting point for your research</h2><a href="#library">View condition library →</a></div><p class="sub">Understand the conditions that can be harder to put a name to.</p>${conditionCards(DATA.conditions.slice(0,3))}</section><div class="trustbar"><span>♧ Linked to original sources</span><span>☑ Credibility made transparent</span><span>♡ Built around patients</span></div>`}
function searchGo(q){location.hash='library/'+encodeURIComponent(q)}
const aliases={dizzy:'dizziness',dizzyness:'dizziness',dizzines:'dizziness',tired:'fatigue',exhausted:'fatigue',tummy:'abdominal pain',stomach:'abdominal pain',poop:'constipation',heart:'racing heart',brainfog:'brain fog',migrane:'migraine',headake:'headache',period:'painful periods'};
function matches(q){q=q.toLowerCase().trim();let normalized=q;Object.keys(aliases).forEach(k=>{if(q.includes(k))normalized+=' '+aliases[k]});return DATA.conditions.filter(c=>[c.name,...c.symptoms,c.category,c.id].some(s=>normalized.split(/\s+/).some(w=>w.length>3&&s.toLowerCase().includes(w)))||c.id===q)}
function library(q=''){let cs=q?matches(q):DATA.conditions;return `${title('THE CONDITION LIBRARY','Make sense of what you’re feeling.','Six introductory guides. Symptoms overlap; this library cannot determine your diagnosis.')}<form class="searchbox" onsubmit="event.preventDefault();searchGo(this.q.value)"><input name="q" value="${esc(q)}" placeholder="Search symptoms, everyday words, or conditions" aria-label="Search library"><button class="primary">Search</button></form>${q?`<p class="sub" style="margin-top:18px">${cs.length} educational topics for “${esc(q)}”. These are not ranked by likelihood.</p>`:''}${cs.length?conditionCards(cs):`<div class="notice">We don’t have a clear match in this small library. Try a shorter symptom or one of the suggestions below. No result does not rule out illness.</div><div class="suggestions">${['Dizziness','Fatigue','Headache','Pelvic pain'].map(s=>`<button class="chip" onclick="searchGo('${s}')">${s}</button>`).join('')}</div>`}<p class="fine">${DATA.editorialNote}</p>`}
function article(id){const c=DATA.conditions.find(x=>x.id===id);if(!c)return library();return `<div class="article"><a class="link" href="#library">← Condition library</a>${title(c.category.toUpperCase(),c.name,'An introduction to support a conversation with your clinician.')}<div class="tools"><button class="secondary" onclick="speak()">◖ Listen</button><button class="secondary" onclick="simple=!simple;render()">${simple?'Detailed summary':'Aa Plain language'}</button><button class="secondary" onclick="saveCondition('${id}')">${saved.includes(id)?'✓ Saved':'♧ Save guide'}</button><button class="secondary" onclick="window.print()">Print</button></div><section class="card readable"><h2>Understanding ${names[id]}</h2><p>${simple?c.plain:c.description}</p><h3>Symptoms you might recognize</h3><div class="chips">${c.symptoms.map(s=>`<span class="chip">${s}</span>`).join('')}</div><h3 style="margin-top:25px">How clinicians investigate it</h3><p>${c.diagnosis}</p>${source(c)}</section><div class="notice">Similar symptoms can have different causes. Ask: “What else could explain this, what should we rule out, and when should I follow up?”</div><div class="tools"><button class="primary" onclick="location.hash='medicines/${id}'">Standard treatments →</button><button class="secondary" onclick="location.hash='care/${id}'">Find specialist care ↗</button></div><p class="fine">${DATA.editorialNote}</p></div>`}
function speak(){if(!('speechSynthesis'in window))return toast('Text-to-speech is not supported in this browser.');speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(($('.readable')||$('main')).innerText))}
function saveCondition(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];put('prognos-saved',saved);render()}
function bodyPage(){return `${title('SYMPTOM EXPLORER','Start with where you feel it.','Choose an area, then explore related educational topics.')}<div class="anatomy-container">${bodyMap()}</div><div id="region-result" class="region-result"></div><div class="notice danger">Sudden severe pain, chest pressure, trouble breathing or new weakness? <a href="#emergency">Get emergency help now →</a></div>`}
function region(r){if(!location.hash.startsWith('#body')){location.hash='body';setTimeout(()=>region(r),50);return}const m={Head:['migraine','anemia','pots'],Chest:['pots','anemia'],Abdomen:['ibs','endometriosis'],Pelvis:['endometriosis','ibs'],Arms:[],Legs:['pots']};$('#region-result').innerHTML=`<h2>${r}: topics to explore</h2><p class="sub">Location alone cannot identify a condition. This is a limited, unranked list, not a complete differential diagnosis.</p>${m[r].length?conditionCards(DATA.conditions.filter(c=>m[r].includes(c.id))):'<div class="notice">Our introductory library does not yet cover arm pain. A clinician can assess injury, joint, muscle, nerve and other causes.</div>'}`;$('#region-result').scrollIntoView({behavior:'smooth',block:'nearest'})}
function medicines(id){let cs=id?DATA.conditions.filter(c=>c.id===id):DATA.conditions;return `${title('MEDICINE MATRIX','Understand the treatment, too.','An encyclopedia of example medicine classes and supportive measures—not a prescription.')}<label for="treatment-filter">Explore standard treatments by condition</label><select id="treatment-filter" onchange="location.hash='medicines/'+this.value"><option value="">All introductory entries</option>${DATA.conditions.map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${names[c.id]}</option>`).join('')}</select><div class="notice">These are examples, not complete treatment guidelines. Suitability, interactions and dosing need a clinician or pharmacist. Risks listed here are not exhaustive.</div><div class="stack readable">${cs.map(c=>`<section class="card"><div class="sectionhead"><h2>${names[c.id]}</h2><a href="#condition/${c.id}">Condition guide ↗</a></div>${c.treatments.map(t=>`<h3 style="margin-top:24px">${t.name}</h3><p>${t.action}</p><p><b>Common side effects & important cautions:</b> ${t.risks}</p><a class="link" href="${t.url}" target="_blank" rel="noopener">Medicine information & risks ↗</a>`).join('')}<hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3>Supportive, non-drug approaches</h3><p>${c.selfcare.text}</p><p><b>Possible downsides & cautions:</b> ${c.selfcare.risks}</p><a class="link" href="${c.selfcare.url}" target="_blank" rel="noopener">Read the supporting source ↗</a>${source(c)}</section>`).join('')}</div><div class="tools"><button class="secondary" onclick="speak()">◖ Listen</button><button class="primary" onclick="location.hash='calendar'">Add your existing medicine schedule →</button></div>`}
function care(id){let ps=id?DATA.providers.filter(p=>p.conditionIds.includes(id)):DATA.providers;return `${title('FIND SPECIALIST CARE','A more informed next conversation.','Explore programs with a focus on the condition you’re researching.')}<label for="care-filter">Condition</label><select id="care-filter" onchange="location.hash='care/'+this.value"><option value="">All programs</option>${DATA.conditions.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${names[c.id]}</option>`).join('')}</select><div class="notice">${DATA.providerNote} Directory currently covers US programs.</div><div class="stack">${ps.length?ps.map(p=>`<section class="card"><span class="eyebrow">${p.specialty}</span><h2 style="margin-top:12px">${p.name}</h2><p class="muted">${p.location}</p><p>${p.credentials}</p>${p.note?`<p>${p.note}</p>`:''}<div class="tools"><a class="primary" style="text-decoration:none" href="${p.url}" target="_blank" rel="noopener">Program & appointments ↗</a><a class="secondary" href="tel:${p.phone}">${p.phone}</a></div></section>`).join(''):'<div class="card">No specialty program is listed for this condition yet. Ask primary care about gastroenterology for IBS, endocrinology for thyroid concerns, or hematology for complex anemia. Confirm the appropriate referral with your clinician.</div>'}</div>`}
function mission(){return `${title('WHY WE EXIST','You deserve to be heard.','Better information can make the path to understanding less lonely.')}<section class="mission"><div class="brand"><span class="brandmark">✳</span>prognos.</div><h1>Less uncertainty.<br>More informed conversations.</h1><p style="max-width:670px">When symptoms persist without clear answers, knowing what to ask next matters. Prognos makes credible health information easier to find, understand and bring into your care—not a substitute for the people who care for you.</p></section><div class="stats">${DATA.statistics.map(s=>`<section class="card"><div class="stat">${s.value}</div><h3>${s.label}</h3><p class="muted">${s.year}</p><p>${s.caveat}</p><a class="link" href="${s.url}" target="_blank" rel="noopener">${s.source} ↗</a></section>`).join('')}</div><div class="card"><h2>Credibility you can inspect</h2><p>Every guide links to original patient information from national health agencies or academic medical centers. Institutional credentials describe the source—not an endorsement of Prognos.</p><p>${DATA.editorialNote}</p><p class="muted">This first edition contains six condition guides. It is not a comprehensive medical reference. Sources checked ${DATA.checked}.</p></div>`}
function emergency(){return `${title('URGENT HELP','If this feels like an emergency, act now.','This app cannot evaluate emergencies or contact services on your behalf.')}<section class="card danger"><h2>Call emergency services for severe or sudden symptoms</h2><p>Chest pressure, severe trouble breathing, stroke signs (face drooping, arm weakness, speech difficulty), sudden severe headache, uncontrolled bleeding, or loss of consciousness need urgent help. If you are unsure and symptoms are severe, call.</p><div class="tools"><a class="primary" href="tel:911">US / Canada · Call 911</a><a class="secondary" href="tel:112">EU · Call 112</a><a class="secondary" href="tel:999">UK · Call 999</a></div><p>Use the number for your current location. Tell the dispatcher where you are and follow their instructions. Do not drive yourself if seriously unwell.</p><a href="https://medlineplus.gov/ency/article/001927.htm" target="_blank" rel="noopener">Emergency warning signs · MedlinePlus ↗</a></section><div class="grid"><section class="card"><h2>Poison or medication exposure</h2><p>US Poison Control: confidential, expert help.</p><a class="primary" href="tel:18002221222">1-800-222-1222</a><p><a href="https://www.poisonhelp.org/" target="_blank" rel="noopener">Poison Help ↗</a></p></section><section class="card"><h2>Suicide & crisis support</h2><p>In the US, call or text 988 for immediate crisis support. For immediate physical danger, call 911.</p><a class="primary" href="tel:988">Call 988</a><p><a href="https://988lifeline.org/" target="_blank" rel="noopener">988 Lifeline ↗</a></p></section></div>`}
function calendar(){let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()+i);return d});return `${title('MY CARE CALENDAR','A little structure for your day.','Record the schedule on your prescription or label. Prognos does not calculate doses.')}<div class="tools"><button class="primary" onclick="medForm()">＋ Add a medicine</button><button class="secondary" onclick="exportCalendar()">↓ Export offline alarms</button><button class="secondary" onclick="window.print()">Print schedule</button></div><div class="notice">Your schedule is saved on this device. Export it to a native calendar for alarms without internet, then confirm alerts are enabled there. This website cannot guarantee background reminders. Do not use reminder completion as medical advice for missed doses.</div><div class="week">${days.map(d=>`<button class="day ${d.toLocaleDateString('en-CA')===selectedDate?'active':''}" onclick="selectedDate='${d.toLocaleDateString('en-CA')}';render()"><small>${d.toLocaleDateString('en-US',{weekday:'short'})}</small>${d.getDate()}</button>`).join('')}</div><div class="card"><h2>${esc(selectedDate)} · Your schedule</h2>${meds.length?meds.flatMap(m=>m.times.map(t=>({...m,time:t}))).sort((a,b)=>a.time.localeCompare(b.time)).map(m=>{let key=selectedDate+'-'+m.id+'-'+m.time,done=get('prognos-done',[]).includes(key);return `<div class="dose"><div><b>${m.time}</b> &nbsp; ${esc(m.name)}<small>${esc(m.dose)} · ${esc(m.instructions||'Follow your prescription or label')}</small></div><div><button class="secondary" onclick="toggleDose('${key}')">${done?'✓ Marked taken':'Mark taken'}</button> <button class="secondary" aria-label="Edit ${esc(m.name)}" onclick="medForm('${m.id}')">Edit</button></div></div>`}).join(''):'<div class="empty">No medicines added yet.<p>Add your own medicine, dose and exact times to build a daily routine.</p></div>'}</div>`}
function medForm(id){let m=meds.find(x=>x.id===id)||{name:'',dose:'',times:['08:00'],instructions:''};$('#modal').innerHTML=`<h2>${id?'Edit':'Add'} your medicine</h2><p class="sub">Copy your prescribed directions. Only daily schedules are supported.</p><form id="medform"><div class="fields"><div><label>Medicine name<input name="name" value="${esc(m.name)}" required maxlength="100"></label></div><div><label>Dose with unit<input name="dose" placeholder="e.g. 1 tablet (as prescribed)" value="${esc(m.dose)}" required maxlength="100"></label></div><div><label>Times per day<select name="frequency" onchange="document.querySelector('#timefields').innerHTML=Array.from({length:+this.value},(_,i)=>'<label>Time '+(i+1)+'<input type=time name=time required></label>').join('')">${[1,2,3,4,5,6].map(n=>`<option ${m.times.length===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div id="timefields">${m.times.map((t,i)=>`<label>Time ${i+1}<input name="time" type="time" value="${t}" required></label>`).join('')}</div></div><label>Label instructions<textarea name="instructions" maxlength="300">${esc(m.instructions)}</textarea></label><button class="primary">Save schedule</button> <button type="button" class="secondary" onclick="$('#modal').close()">Cancel</button>${id?` <button type="button" class="secondary" onclick="removeMed('${id}')">Delete medicine</button>`:''}</form>`;$('#modal').showModal();$('#medform').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),times=f.getAll('time');if(new Set(times).size!==times.length)return toast('Choose a different time for each dose.');let entry={id:id||crypto.randomUUID(),name:f.get('name').trim(),dose:f.get('dose').trim(),times,instructions:f.get('instructions').trim()};if(!entry.name||!entry.dose)return;meds=meds.filter(x=>x.id!==id);meds.push(entry);put('prognos-meds',meds);$('#modal').close();render();toast('Daily schedule saved on this device')}}
function removeMed(id){meds=meds.filter(m=>m.id!==id);put('prognos-meds',meds);$('#modal').close();render()}
function toggleDose(k){let d=get('prognos-done',[]);put('prognos-done',d.includes(k)?d.filter(x=>x!==k):[...d,k]);render()}
function exportCalendar(){if(!meds.length)return toast('Add a medicine first.');const ics=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Prognos//Care Calendar//EN','CALSCALE:GREGORIAN'];const now=new Date(),date=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('');for(let m of meds)for(let t of m.times)lines.push('BEGIN:VEVENT','UID:'+m.id+'-'+t.replace(':','')+'@prognos','DTSTAMP:'+now.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+date+'T'+t.replace(':','')+'00','DURATION:PT5M','RRULE:FREQ=DAILY','SUMMARY:'+ics(m.name+' — '+m.dose),'DESCRIPTION:'+ics(m.instructions||'Follow prescribed instructions. Do not double a missed dose without advice.'),'BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:Medicine schedule','END:VALARM','END:VEVENT');lines.push('END:VCALENDAR');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\r\n')],{type:'text/calendar'}));a.download='prognos-care-schedule.ics';a.click();URL.revokeObjectURL(a.href);toast('Import into your calendar and verify alarms. Re-imports may duplicate events.')}
function consultant(){return `${title('AI CONSULTANT','Bring your questions.','A space to understand the information and prepare for your next appointment.')}<div class="chat"><div class="notice"><b>Source-guided preview · Live AI is not connected.</b><br>This version retrieves matching library guides; it does not generate personalized medical answers. No messages are sent to a model or stored after reloading.</div><div class="tools">${['What can cause dizziness when standing?','Tell me about migraine','How do I prepare for a doctor visit?'].map(q=>`<button class="chip" onclick="ask('${q}')">${q}</button>`).join('')}</div><div id="messages" aria-live="polite">${chat.map(m=>`<div class="bubble ${m.role}">${m.html}</div>`).join('')}</div><form class="searchbox" onsubmit="event.preventDefault();ask(this.q.value);this.reset()"><input name="q" required aria-label="Your question" placeholder="Ask about symptoms or a condition…"><button class="primary">Ask ↗</button></form><p class="fine">If you have severe or sudden symptoms, <a href="#emergency">seek urgent help</a>. Never wait for an app response.</p></div>`}
function askPreset(q){location.hash='consultant';setTimeout(()=>ask(q),50)}
function ask(q){if(!q.trim())return;chat.push({role:'user',html:esc(q)});let html;if(/chest pain|can't breathe|cannot breathe|suicid|stroke|worst headache|severe pain|overdose/i.test(q))html='These words can describe an emergency. This tool cannot assess urgency. If symptoms are severe or sudden, contact emergency services now. <a href="#emergency">Open urgent help →</a>';else if(/appointment|doctor visit|prepare/i.test(q))html='To organize your next conversation, write down when symptoms started, what changes them, medicines and supplements you use, and questions you want answered. Ask what the next steps are and when to follow up. <a href="https://www.nia.nih.gov/health/medical-care-and-appointments/how-prepare-doctors-appointment" target="_blank" rel="noopener">Appointment preparation · National Institute on Aging ↗</a>';else{let cs=matches(q);html=cs.length?'Here are matching educational topics from this limited library. They cannot establish what is causing your symptoms.<br>'+cs.slice(0,3).map(c=>`<h3>${names[c.id]}</h3><p>${c.plain}</p><a href="#condition/${c.id}">Explore the guide →</a>${source(c)}`).join(''):'I could not find a clear topic in this introductory library. Try a symptom such as “dizziness,” “fatigue,” or “abdominal pain.” A lack of results does not rule out a medical problem.'}chat.push({role:'assistant',html});render();$('#messages').lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'})}
function settings(){return `${title('MAKE YOURSELF COMFORTABLE','Your app, your pace.','Choose how Prognos looks and how you read it.')}<section class="card"><h2>Appearance</h2><div class="themes">${[['sage','Sage','Calm & familiar'],['ocean','Ocean','Cool & clear'],['night','Night','A softer glow']].map(([k,n,d])=>`<button class="theme ${get('prognos-theme','sage')===k?'selected':''}" onclick="put('prognos-theme','${k}');applySettings();render()"><b>${n}</b><p>${d}</p></button>`).join('')}</div><h2>Reading comfort</h2><div class="tools"><button class="secondary" onclick="put('prognos-large',!get('prognos-large',false));applySettings();render()">${get('prognos-large',false)?'✓ Larger':'Standard'} text</button><button class="secondary" onclick="simple=!simple;toast(simple?'Plain-language summaries enabled':'Detailed summaries enabled')">Toggle plain-language summaries</button><button class="secondary" onclick="speechSynthesis.cancel()">Stop reading aloud</button></div></section><section class="card" style="margin-top:20px"><h2>Saved guides</h2>${saved.length?conditionCards(DATA.conditions.filter(c=>saved.includes(c.id))):'<p class="muted">Save a guide from its condition page to find it here.</p>'}<h2 style="margin-top:25px">Your device, your information</h2><p>Medication schedules and preferences are stored in this browser, not encrypted as a medical record. Anyone with access to this browser may see them. Clearing browser storage removes them. No account sync is provided.</p><button class="secondary" onclick="clearData()">Clear my saved information</button></section>`}
function clearData(){if(!confirm('Delete saved medication schedules, completion history and saved guides on this device?'))return;['prognos-meds','prognos-done','prognos-saved'].forEach(k=>localStorage.removeItem(k));meds=[];saved=[];render();toast('Saved information cleared')}
function applySettings(){document.body.dataset.theme=get('prognos-theme','sage');document.body.classList.toggle('large',get('prognos-large',false))}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function render(){const [page='home',raw='']=location.hash.slice(1).split('/');let arg;try{arg=decodeURIComponent(raw)}catch{arg=''}$('#nav').innerHTML=navs.map(([id,i,n])=>`<a href="#${id}" class="${page===id||page==='condition'&&id==='library'?'active':''}"><i>${i}</i>${n}</a>`).join('');$('#main').innerHTML=({home,library:()=>library(arg),condition:()=>article(arg),body:bodyPage,medicines:()=>medicines(arg),calendar,care:()=>care(arg),mission,emergency,consultant,settings}[page]||home)();document.querySelectorAll('[data-region]').forEach(g=>{g.onclick=()=>region(g.dataset.region);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();region(g.dataset.region)}}});applySettings()}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===document.querySelector('.anatomy-frame')?.contentWindow&&e.data?.type==='prognos-region'&&['Head','Chest','Abdomen','Pelvis','Arms','Legs'].includes(e.data.region))region(e.data.region)});
window.addEventListener('hashchange' ,()=>{render();window.scrollTo(0,0)});function connection(){$('#connection').textContent=navigator.onLine?'Online':'Offline · saved access'}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
